    {'technology': 'mysql', 'topic': 'select', 'name': 'Select Specific Columns', 'slug': 'select-specific-columns', 'description': 'A students table has columns id, name, and score. Write a query that returns only the name and score columns, for every row, ordered by id.', 'input_format': 'There is no input for this problem; the students table already exists with sample data.', 'output_format': "Print each row's name and score.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'output': 'Ana|82\nBen|59'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- Select name and score, ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'Ana|82\nBen|59\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91),(2,'Dee',40),(3,'Eli',65);", 'Cy|91\nDee|40\nEli|65\n', True, 1)], 'reference_query': 'SELECT name, score FROM students ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'select', 'name': 'Select With a Column Alias', 'slug': 'select-with-a-column-alias', 'description': 'A students table has columns id, name, and score. Write a query that returns the name column renamed to student_name using AS, ordered by id.', 'input_format': 'There is no input for this problem; the students table already exists with sample data.', 'output_format': "Print each row's name (as the aliased column).", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'output': 'Ana\nBen'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': '-- Select name AS student_name, ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'Ana\nBen\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91),(2,'Dee',40);", 'Cy\nDee\n', True, 1)], 'reference_query': 'SELECT name AS student_name FROM students ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'select', 'name': 'Select Distinct Values', 'slug': 'select-distinct-values', 'description': 'An employees table has columns id and department. Write a query that returns each distinct department name that appears in the table, ordered alphabetically.', 'input_format': 'There is no input for this problem; the employees table already exists with sample data.', 'output_format': 'Print each distinct department name, one per row.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, department TEXT);\nINSERT INTO employees VALUES (1,'Sales'),(2,'Sales'),(3,'IT'),(4,'HR'),(5,'IT');", 'output': 'HR\nIT\nSales'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 3, 'starter': '-- Select DISTINCT department, ordered alphabetically\n', 'tests': [("CREATE TABLE employees(id INTEGER, department TEXT);\nINSERT INTO employees VALUES (1,'Sales'),(2,'Sales'),(3,'IT'),(4,'HR'),(5,'IT');", 'HR\nIT\nSales\n', False, 1), ("CREATE TABLE employees(id INTEGER, department TEXT);\nINSERT INTO employees VALUES (1,'Ops'),(2,'Ops'),(3,'Ops');", 'Ops\n', True, 1)], 'reference_query': 'SELECT DISTINCT department FROM employees ORDER BY department;'},
    {'technology': 'mysql', 'topic': 'select', 'name': 'Select a Concatenated Column', 'slug': 'select-a-concatenated-column', 'description': 'A students table has columns id, name, and score. Write a query that returns one text column per row: the name, followed by a colon and a space, followed by the score (e.g. Ana: 82). Use || to concatenate. Order by id.', 'input_format': 'There is no input for this problem; the students table already exists with sample data.', 'output_format': 'Print each row as NAME: SCORE.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'output': 'Ana: 82\nBen: 59'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': "-- Select name || ': ' || score, ordered by id\n", 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'Ana: 82\nBen: 59\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91),(2,'Dee',40),(3,'Eli',65);", 'Cy: 91\nDee: 40\nEli: 65\n', True, 1)], 'reference_query': "SELECT name || ': ' || score FROM students ORDER BY id;"},
    {'technology': 'mysql', 'topic': 'select', 'name': 'Select a Computed Column', 'slug': 'select-a-computed-column', 'description': 'A students table has columns id, name, and score. Write a query that returns the name and a bonus column equal to score + 5, for every row, ordered by id.', 'input_format': 'There is no input for this problem; the students table already exists with sample data.', 'output_format': "Print each row's name and score + 5.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'output': 'Ana|87\nBen|64'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- Select name and score + 5, ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'Ana|87\nBen|64\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91),(2,'Dee',40),(3,'Eli',65);", 'Cy|96\nDee|45\nEli|70\n', True, 1)], 'reference_query': 'SELECT name, score + 5 FROM students ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'where', 'name': 'Filter by Equality', 'slug': 'filter-by-equality', 'description': 'A students table has columns id, name, and score. Write a query that returns the name of every student whose score is exactly 90, ordered by id.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'Print the name of each student scoring exactly 90.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',90),(2,'Ben',59),(3,'Cy',90);", 'output': 'Ana\nCy'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- Select name where score = 90, ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',90),(2,'Ben',59),(3,'Cy',90);", 'Ana\nCy\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',90),(2,'Eli',20);", 'Dee\n', True, 1)], 'reference_query': 'SELECT name FROM students WHERE score = 90 ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'where', 'name': 'Filter by Range', 'slug': 'filter-by-range', 'description': 'A students table has columns id, name, and score. Write a query that returns the name of every student whose score is between 60 and 80 inclusive, ordered by id.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'Print the name of each qualifying student.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',70),(3,'Cy',40);", 'output': 'Ben'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': '-- Select name where score is between 60 and 80, ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',70),(3,'Cy',40);", 'Ben\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',60),(2,'Eli',80),(3,'Fay',81);", 'Dee\nEli\n', True, 1)], 'reference_query': 'SELECT name FROM students WHERE score BETWEEN 60 AND 80 ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'where', 'name': 'Filter With AND', 'slug': 'filter-with-and', 'description': 'An employees table has columns id, name, department, and salary. Write a query that returns the name of every employee in the IT department earning more than 50000, ordered by id.', 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': 'Print the name of each qualifying employee.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',60000),(2,'Ben','IT',40000),(3,'Cy','HR',70000);", 'output': 'Ana'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 3, 'starter': "-- Select name where department = 'IT' AND salary > 50000, ordered by id\n", 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',60000),(2,'Ben','IT',40000),(3,'Cy','HR',70000);", 'Ana\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','IT',90000),(2,'Eli','Sales',90000);", 'Dee\n', True, 1)], 'reference_query': "SELECT name FROM employees WHERE department = 'IT' AND salary > 50000 ORDER BY id;"},
    {'technology': 'mysql', 'topic': 'where', 'name': 'Filter With OR', 'slug': 'filter-with-or', 'description': 'An employees table has columns id, name, department, and salary. Write a query that returns the name of every employee in the HR or Sales department, ordered by id.', 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': 'Print the name of each qualifying employee.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',60000),(2,'Ben','HR',40000),(3,'Cy','Sales',70000);", 'output': 'Ben\nCy'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': "-- Select name where department = 'HR' OR department = 'Sales', ordered by id\n", 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',60000),(2,'Ben','HR',40000),(3,'Cy','Sales',70000);", 'Ben\nCy\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','HR',1),(2,'Eli','IT',2),(3,'Fay','Sales',3);", 'Dee\nFay\n', True, 1)], 'reference_query': "SELECT name FROM employees WHERE department = 'HR' OR department = 'Sales' ORDER BY id;"},
    {'technology': 'mysql', 'topic': 'where', 'name': 'Filter With Not Equal', 'slug': 'filter-with-not-equal', 'description': 'An employees table has columns id, name, department, and salary. Write a query that returns the name of every employee who is not in the IT department, ordered by id.', 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': 'Print the name of each employee outside IT.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',1),(2,'Ben','HR',2),(3,'Cy','Sales',3);", 'output': 'Ben\nCy'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': "-- Select name where department <> 'IT', ordered by id\n", 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',1),(2,'Ben','HR',2),(3,'Cy','Sales',3);", 'Ben\nCy\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','Ops',1),(2,'Eli','IT',2);", 'Dee\n', True, 1)], 'reference_query': "SELECT name FROM employees WHERE department <> 'IT' ORDER BY id;"},
    {'technology': 'mysql', 'topic': 'order-by', 'name': 'Sort Ascending', 'slug': 'sort-ascending', 'description': 'A students table has columns id, name, and score. Write a query that returns every name and score, sorted by score from lowest to highest.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': "Print each row's name and score, lowest score first.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40),(3,'Cy',91);", 'output': 'Ben|40\nAna|82\nCy|91'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- Select name and score, ordered by score ascending\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40),(3,'Cy',91);", 'Ben|40\nAna|82\nCy|91\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',5),(2,'Eli',3),(3,'Fay',9);", 'Eli|3\nDee|5\nFay|9\n', True, 1)], 'reference_query': 'SELECT name, score FROM students ORDER BY score ASC;'},
    {'technology': 'mysql', 'topic': 'order-by', 'name': 'Sort Descending', 'slug': 'sort-descending', 'description': 'A students table has columns id, name, and score. Write a query that returns every name and score, sorted by score from highest to lowest.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': "Print each row's name and score, highest score first.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40),(3,'Cy',91);", 'output': 'Cy|91\nAna|82\nBen|40'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': '-- Select name and score, ordered by score descending\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40),(3,'Cy',91);", 'Cy|91\nAna|82\nBen|40\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',5),(2,'Eli',3),(3,'Fay',9);", 'Fay|9\nDee|5\nEli|3\n', True, 1)], 'reference_query': 'SELECT name, score FROM students ORDER BY score DESC;'},
    {'technology': 'mysql', 'topic': 'order-by', 'name': 'Sort by Multiple Columns', 'slug': 'sort-by-multiple-columns', 'description': 'An employees table has columns id, name, department, and salary. Write a query that returns name and department, sorted by department alphabetically, then by name alphabetically within each department.', 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': "Print each row's name and department, sorted as described.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ben','IT',1),(2,'Ana','IT',2),(3,'Cy','HR',3);", 'output': 'Cy|HR\nAna|IT\nBen|IT'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 3, 'starter': '-- Select name and department, ordered by department then name\n', 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ben','IT',1),(2,'Ana','IT',2),(3,'Cy','HR',3);", 'Cy|HR\nAna|IT\nBen|IT\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Zed','Ops',1),(2,'Amy','Ops',2),(3,'Bob','HR',3);", 'Bob|HR\nAmy|Ops\nZed|Ops\n', True, 1)], 'reference_query': 'SELECT name, department FROM employees ORDER BY department ASC, name ASC;'},
    {'technology': 'mysql', 'topic': 'order-by', 'name': 'Sort Text Alphabetically', 'slug': 'sort-text-alphabetically', 'description': 'A students table has columns id, name, and score. Write a query that returns every name, sorted alphabetically.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'Print each name in alphabetical order.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',1),(2,'Ana',2),(3,'Ben',3);", 'output': 'Ana\nBen\nCy'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': '-- Select name, ordered alphabetically\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',1),(2,'Ana',2),(3,'Ben',3);", 'Ana\nBen\nCy\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Zed',1),(2,'Amy',2);", 'Amy\nZed\n', True, 1)], 'reference_query': 'SELECT name FROM students ORDER BY name ASC;'},
    {'technology': 'mysql', 'topic': 'order-by', 'name': 'Sort by a Computed Expression', 'slug': 'sort-by-a-computed-expression', 'description': 'A students table has columns id, name, and score. Write a query that returns each name and score, sorted by score * -1 ascending (equivalent to sorting score descending, but the expression itself must appear in the ORDER BY).', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': "Print each row's name and score, highest score first.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40),(3,'Cy',91);", 'output': 'Cy|91\nAna|82\nBen|40'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- Select name and score, ordered by score * -1 ascending\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40),(3,'Cy',91);", 'Cy|91\nAna|82\nBen|40\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',5),(2,'Eli',3),(3,'Fay',9);", 'Fay|9\nDee|5\nEli|3\n', True, 1)], 'reference_query': 'SELECT name, score FROM students ORDER BY score * -1 ASC;'},
    {'technology': 'mysql', 'topic': 'limit', 'name': 'First N Rows', 'slug': 'first-n-rows', 'description': 'A students table has columns id, name, and score. Write a query that returns the name of the first 2 students by id.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'Print the name of the first 2 students, ordered by id.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',1),(2,'Ben',2),(3,'Cy',3);", 'output': 'Ana\nBen'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- Select name, ordered by id, limited to 2 rows\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',1),(2,'Ben',2),(3,'Cy',3);", 'Ana\nBen\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',1),(2,'Eli',2),(3,'Fay',3),(4,'Gus',4);", 'Dee\nEli\n', True, 1)], 'reference_query': 'SELECT name FROM students ORDER BY id LIMIT 2;'},
    {'technology': 'mysql', 'topic': 'limit', 'name': 'Skip and Take', 'slug': 'skip-and-take', 'description': 'A students table has columns id, name, and score. Write a query that skips the first 2 students by id and returns the next 2.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'Print the name of students 3 and 4 by id order.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',1),(2,'Ben',2),(3,'Cy',3),(4,'Dee',4),(5,'Eli',5);", 'output': 'Cy\nDee'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': '-- Select name, ordered by id, skipping 2 rows, taking the next 2\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',1),(2,'Ben',2),(3,'Cy',3),(4,'Dee',4),(5,'Eli',5);", 'Cy\nDee\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'S1',1),(2,'S2',2),(3,'S3',3),(4,'S4',4),(5,'S5',5),(6,'S6',6),(7,'S7',7);", 'S3\nS4\n', True, 1)], 'reference_query': 'SELECT name FROM students ORDER BY id LIMIT 2 OFFSET 2;'},
    {'technology': 'mysql', 'topic': 'limit', 'name': 'Top N by Score', 'slug': 'top-n-by-score', 'description': 'A students table has columns id, name, and score. Write a query that returns the name of the top 2 students by score, highest first.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'Print the name of the top 2 scorers.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40),(3,'Cy',91);", 'output': 'Cy\nAna'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 3, 'starter': '-- Select name, ordered by score descending, limited to 2 rows\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',40),(3,'Cy',91);", 'Cy\nAna\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',5),(2,'Eli',30),(3,'Fay',9),(4,'Gus',60);", 'Gus\nEli\n', True, 1)], 'reference_query': 'SELECT name FROM students ORDER BY score DESC LIMIT 2;'},
