    {'technology': 'mysql', 'topic': 'insert', 'name': 'Insert Multiple Rows', 'slug': 'insert-multiple-rows', 'description': "A students table has columns id, name, and score. Above the provided SELECT statement, write a single INSERT statement that adds two new rows in one statement: (97, 'Amy', 70) and (98, 'Bo', 75).", 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'The provided SELECT prints every row, including your two new ones, ordered by id.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82);", 'output': '1|Ana|82\n97|Amy|70\n98|Bo|75'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': "-- Write one INSERT that adds (97,'Amy',70) and (98,'Bo',75)\n-- Do not modify the line below; it shows you the table afterward.\nSELECT id, name, score FROM students ORDER BY id;\n", 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82);", '1|Ana|82\n97|Amy|70\n98|Bo|75\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91),(2,'Dee',40);", '1|Cy|91\n2|Dee|40\n97|Amy|70\n98|Bo|75\n', True, 1)], 'reference_query': "INSERT INTO students VALUES (97, 'Amy', 70), (98, 'Bo', 75);\nSELECT id, name, score FROM students ORDER BY id;"},
