    {'technology': 'mysql', 'topic': 'insert', 'name': 'Insert a Computed Value', 'slug': 'insert-a-computed-value', 'description': "A students table has columns id, name, and score. Above the provided SELECT statement, write an INSERT statement that adds the row (95, 'Dax', 40 + 10) -- let the database compute the score as an expression.", 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': "The provided SELECT prints every row; your new row's score should be 50.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82);", 'output': '1|Ana|82\n95|Dax|50'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': "-- Write an INSERT that adds (95,'Dax', 40 + 10)\n-- Do not modify the line below; it shows you the table afterward.\nSELECT id, name, score FROM students ORDER BY id;\n", 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82);", '1|Ana|82\n95|Dax|50\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91);", '1|Cy|91\n95|Dax|50\n', True, 1)], 'reference_query': "INSERT INTO students VALUES (95, 'Dax', 40 + 10);\nSELECT id, name, score FROM students ORDER BY id;"},
    {'technology': 'mysql', 'topic': 'insert', 'name': 'Insert From Another Table', 'slug': 'insert-from-another-table', 'description': 'A students table and an archive_students table both have columns id, name, and score; archive_students already has one row. Above the provided SELECT statement, write an INSERT ... SELECT statement that copies every row from archive_students into students.', 'input_format': 'There is no input; both tables already exist with sample data.', 'output_format': 'The provided SELECT prints every row in students, including the copied one, ordered by id.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82);\nCREATE TABLE archive_students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO archive_students VALUES (50, 'Old', 20);", 'output': '1|Ana|82\n50|Old|20'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- Write INSERT INTO students SELECT * FROM archive_students\n-- Do not modify the line below; it shows you the table afterward.\nSELECT id, name, score FROM students ORDER BY id;\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82);\nCREATE TABLE archive_students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO archive_students VALUES (50, 'Old', 20);", '1|Ana|82\n50|Old|20\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91);\nCREATE TABLE archive_students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO archive_students VALUES (60, 'Prior', 5);", '1|Cy|91\n60|Prior|5\n', True, 1)], 'reference_query': 'INSERT INTO students SELECT * FROM archive_students;\nSELECT id, name, score FROM students ORDER BY id;'},
