    {'technology': 'mysql', 'topic': 'index-fundamentals', 'name': 'Drop an Index', 'slug': 'drop-an-index', 'description': 'A students table already has two indexes: idx_old on students(score) and idx_keep on students(name). Above the provided query, write a DROP INDEX statement that removes idx_old only.', 'input_format': 'There is no input; the students table and both indexes already exist.', 'output_format': 'The provided query lists the names of the remaining index(es) on students; only idx_keep should remain.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82);\nCREATE INDEX idx_old ON students(score);\nCREATE INDEX idx_keep ON students(name);", 'output': 'idx_keep'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': "-- Write DROP INDEX idx_old (leave idx_keep alone)\n-- Do not modify the line below.\nSELECT name FROM pragma_index_list('students') ORDER BY name;\n", 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82);\nCREATE INDEX idx_old ON students(score);\nCREATE INDEX idx_keep ON students(name);", 'idx_keep\n', False, 1)], 'reference_query': "DROP INDEX idx_old;\nSELECT name FROM pragma_index_list('students') ORDER BY name;"},
