    {'technology': 'javascript', 'topic': 'conditions', 'name': 'Combining Conditions', 'slug': 'combining-conditions', 'description': 'Read one integer and print FizzBuzz if divisible by both 3 and 5, Fizz if only by 3, Buzz if only by 5, otherwise print the number itself.', 'input_format': 'One integer n.', 'output_format': 'Print FizzBuzz, Fizz, Buzz, or n.', 'constraints': 'None.', 'examples': [{'input': '15', 'output': 'FizzBuzz'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 4, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\n// FizzBuzz logic\n", 'tests': [('15\n', 'FizzBuzz\n', False, 1), ('9\n', 'Fizz\n', False, 1), ('10\n', 'Buzz\n', True, 2), ('7\n', '7\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst n = Number(input);\nif (n % 15 === 0) {\n  console.log('FizzBuzz');\n} else if (n % 3 === 0) {\n  console.log('Fizz');\n} else if (n % 5 === 0) {\n  console.log('Buzz');\n} else {\n  console.log(n);\n}\n"},
