    {'technology': 'javascript', 'topic': 'functions', 'name': 'An Arrow Function', 'slug': 'an-arrow-function', 'description': 'Write an arrow function square that returns its argument squared. Read one integer, call square on it, and print the result.', 'input_format': 'One integer n.', 'output_format': 'Print n squared.', 'constraints': 'None.', 'examples': [{'input': '4', 'output': '16'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 2, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst square = (x) => {\n  // Return x squared\n};\nconsole.log(square(Number(input)));\n", 'tests': [('4\n', '16\n', False, 1), ('-3\n', '9\n', False, 1), ('0\n', '0\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nconst square = (x) => x * x;\nconsole.log(square(Number(input)));\n"},
    {'technology': 'javascript', 'topic': 'functions', 'name': 'Default Parameters', 'slug': 'default-parameters', 'description': "Write a function greet(name) with a default parameter value of 'Guest', returning 'Hello, ' followed by the name. Read one line of text; if it is empty, call greet with no argument, otherwise pass the text.", 'input_format': 'One line of text, possibly empty.', 'output_format': 'Print the greeting.', 'constraints': 'None.', 'examples': [{'input': 'Alice', 'output': 'Hello, Alice'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 3, 'starter': "const input = require('fs').readFileSync(0, 'utf8').replace(/\\n$/, '');\nfunction greet(name = 'Guest') {\n  // Return 'Hello, ' + name\n}\nconsole.log(input === '' ? greet() : greet(input));\n", 'tests': [('Alice\n', 'Hello, Alice\n', False, 1), ('\n', 'Hello, \n', False, 1), ('Bob\n', 'Hello, Bob\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').replace(/\\n$/, '');\nfunction greet(name = 'Guest') {\n  return 'Hello, ' + name;\n}\nconsole.log(input === '' ? greet() : greet(input));\n"},
    {'technology': 'javascript', 'topic': 'functions', 'name': 'A Function That Returns a Function', 'slug': 'a-function-that-returns-a-function', 'description': 'Write a function makeAdder(n) that returns a new function which adds n to its argument. Read two integers, space-separated; use makeAdder on the first to build an adder, then apply it to the second, and print the result.', 'input_format': 'One line containing two integers a and b.', 'output_format': 'Print a + b (computed via makeAdder).', 'constraints': 'None.', 'examples': [{'input': '3 4', 'output': '7'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 4, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nfunction makeAdder(n) {\n  // Return a function that adds n to its argument\n}\nconst [a, b] = input.split(' ').map(Number);\nconsole.log(makeAdder(a)(b));\n", 'tests': [('3 4\n', '7\n', False, 1), ('-2 5\n', '3\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nfunction makeAdder(n) {\n  return function (x) {\n    return x + n;\n  };\n}\nconst [a, b] = input.split(' ').map(Number);\nconst addA = makeAdder(a);\nconsole.log(addA(b));\n"},
    {'technology': 'javascript', 'topic': 'functions', 'name': 'Rest Parameters', 'slug': 'rest-parameters', 'description': 'Write a function total(...nums) that returns the sum of all its arguments using rest parameters. Read a line of space-separated integers, spread them into total, and print the result.', 'input_format': 'One line of space-separated integers.', 'output_format': 'Print their sum.', 'constraints': 'None.', 'examples': [{'input': '1 2 3', 'output': '6'}], 'language': 'javascript', 'language_id': 63, 'difficulty': 'Easy', 'order': 5, 'starter': "const input = require('fs').readFileSync(0, 'utf8').trim();\nfunction total(...nums) {\n  // Return the sum of nums\n}\nconst values = input.split(' ').map(Number);\nconsole.log(total(...values));\n", 'tests': [('1 2 3\n', '6\n', False, 1), ('5\n', '5\n', False, 1), ('-1 -2 -3 -4\n', '-10\n', True, 2)], 'reference_source': "const input = require('fs').readFileSync(0, 'utf8').trim();\nfunction total(...nums) {\n  return nums.reduce((sum, n) => sum + n, 0);\n}\nconst values = input.split(' ').map(Number);\nconsole.log(total(...values));\n"},
