    {'technology': 'pandas', 'topic': 'grouping', 'name': 'Group and Count', 'slug': 'group-and-count-pandas', 'description': 'Read CSV text with columns id, name, department, salary, and print each department alongside how many employees are in it, one department per line as DEPARTMENT COUNT, ordered by department alphabetically.', 'input_format': 'CSV text with a header row.', 'output_format': 'Print each department and its employee count.', 'constraints': 'None.', 'examples': [{'input': 'id,name,department,salary\n1,Ana,IT,1\n2,Ben,IT,2\n3,Cy,HR,3', 'output': 'HR 1\nIT 2'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 1, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# counts = df.groupby('department').size().sort_index(); print dept, count for each\n", 'tests': [('id,name,department,salary\n1,Ana,IT,1\n2,Ben,IT,2\n3,Cy,HR,3\n', 'HR 1\nIT 2\n', False, 1), ('id,name,department,salary\n1,Dee,Ops,1\n2,Eli,IT,2\n3,Fay,HR,3\n4,Gus,HR,4\n', 'HR 2\nIT 1\nOps 1\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ncounts = df.groupby('department').size().sort_index()\nfor dept, count in counts.items():\n    print(dept, count)\n"},
    {'technology': 'pandas', 'topic': 'grouping', 'name': 'Group and Sum', 'slug': 'group-and-sum-pandas', 'description': 'Read CSV text with columns id, name, department, salary, and print each department alongside its total salary, ordered by department alphabetically, as DEPARTMENT TOTAL.', 'input_format': 'CSV text with a header row.', 'output_format': 'Print each department and its total salary.', 'constraints': 'None.', 'examples': [{'input': 'id,name,department,salary\n1,Ana,IT,100\n2,Ben,IT,200\n3,Cy,HR,50', 'output': 'HR 50\nIT 300'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 2, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# totals = df.groupby('department')['salary'].sum().sort_index(); print dept, total for each\n", 'tests': [('id,name,department,salary\n1,Ana,IT,100\n2,Ben,IT,200\n3,Cy,HR,50\n', 'HR 50\nIT 300\n', False, 1), ('id,name,department,salary\n1,Dee,Ops,10\n2,Eli,IT,20\n3,Fay,HR,30\n', 'HR 30\nIT 20\nOps 10\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ntotals = df.groupby('department')['salary'].sum().sort_index()\nfor dept, total in totals.items():\n    print(dept, total)\n"},
