    {'technology': 'pandas', 'topic': 'grouping', 'name': 'Group by Multiple Keys', 'slug': 'group-by-multiple-keys-pandas', 'description': "A students-like CSV has columns id, name, department, salary where salary is repurposed as score, and an extra term column exists implicitly via department values like 'IT-Fall'. Simplify: read columns id, name, department, salary and group by department, computing both count and sum of salary; print DEPARTMENT COUNT SUM, one row per department, ordered alphabetically.", 'input_format': 'CSV text with a header row.', 'output_format': 'Print each department, its count, and its salary sum.', 'constraints': 'None.', 'examples': [{'input': 'id,name,department,salary\n1,Ana,IT,100\n2,Ben,IT,200\n3,Cy,HR,50', 'output': 'HR 1 50\nIT 2 300'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 4, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# grouped = df.groupby('department')['salary'].agg(['count','sum']).sort_index(); print each row\n", 'tests': [('id,name,department,salary\n1,Ana,IT,100\n2,Ben,IT,200\n3,Cy,HR,50\n', 'HR 1 50\nIT 2 300\n', False, 1), ('id,name,department,salary\n1,Dee,Ops,10\n2,Eli,Ops,30\n3,Fay,HR,5\n', 'HR 1 5\nOps 2 40\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ngrouped = df.groupby('department')['salary'].agg(['count', 'sum']).sort_index()\nfor dept, row in grouped.iterrows():\n    print(dept, row['count'], row['sum'])\n"},
