    {'technology': 'pandas', 'topic': 'merging', 'name': 'An Inner Merge', 'slug': 'an-inner-merge', 'description': "Standard input contains two CSV blocks separated by a line containing exactly ---: first a customers table (id, name), then an orders table (id, customer_id, amount). Merge them on customers.id == orders.customer_id using an inner merge, then print name and amount for every matched row, ordered by the order's id.", 'input_format': 'Two CSV blocks separated by a line of exactly ---: customers (id,name), then orders (id,customer_id,amount).', 'output_format': "Print each matched row's name and amount.", 'constraints': 'None.', 'examples': [{'input': 'id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50\n2,2,20', 'output': 'name  amount\n Ana      50\n Ben      20'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 1, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\n# merged = customers.merge(orders, left_on='id', right_on='customer_id', how='inner')\n# sort by the order's id, then print name and amount\n", 'tests': [('id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50\n2,2,20\n', 'name  amount\n Ana      50\n Ben      20\n', False, 1), ('id,name\n1,Cy\n2,Dee\n---\nid,customer_id,amount\n1,1,10\n2,1,15\n', 'name  amount\n  Cy      10\n  Cy      15\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\nmerged = customers.merge(orders, left_on='id', right_on='customer_id', how='inner').sort_values('id_y')\nprint(merged[['name', 'amount']].to_string(index=False))\n"},
    {'technology': 'pandas', 'topic': 'merging', 'name': 'A Left Merge', 'slug': 'a-left-merge', 'description': "Standard input contains two CSV blocks separated by a line containing exactly ---: a customers table (id, name), then an orders table (id, customer_id, amount). Merge with how='left' so every customer appears even with no orders (amount becomes NaN), then print name and amount for every row, ordered by customer id.", 'input_format': 'Two CSV blocks separated by a line of exactly ---: customers (id,name), then orders (id,customer_id,amount).', 'output_format': "Print each customer's name and amount (amount may be NaN).", 'constraints': 'None.', 'examples': [{'input': 'id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50', 'output': 'name  amount\n Ana    50.0\n Ben     NaN'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 2, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\n# merged = customers.merge(orders, left_on='id', right_on='customer_id', how='left')\n# sort by the customer's id, then print name and amount\n", 'tests': [('id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50\n', 'name  amount\n Ana    50.0\n Ben     NaN\n', False, 1), ('id,name\n1,Cy\n2,Dee\n3,Eli\n---\nid,customer_id,amount\n1,2,5\n', 'name  amount\n  Cy     NaN\n Dee     5.0\n Eli     NaN\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\nmerged = customers.merge(orders, left_on='id', right_on='customer_id', how='left').sort_values('id_x')\nprint(merged[['name', 'amount']].to_string(index=False))\n"},
    {'technology': 'pandas', 'topic': 'merging', 'name': 'Merge and Aggregate', 'slug': 'merge-and-aggregate-pandas', 'description': 'Standard input contains two CSV blocks separated by a line containing exactly ---: a customers table (id, name), then an orders table (id, customer_id, amount). Merge them, group by customer name, sum the amount, and print NAME TOTAL for each customer with at least one order, ordered by name.', 'input_format': 'Two CSV blocks separated by a line of exactly ---: customers (id,name), then orders (id,customer_id,amount).', 'output_format': "Print each customer's name and total order amount.", 'constraints': 'None.', 'examples': [{'input': 'id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50\n2,1,30\n3,2,20', 'output': 'Ana 80\nBen 20'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 3, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\n# merged = customers.merge(orders, left_on='id', right_on='customer_id', how='inner')\n# totals = merged.groupby('name')['amount'].sum().sort_index(); print name, total for each\n", 'tests': [('id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50\n2,1,30\n3,2,20\n', 'Ana 80\nBen 20\n', False, 1), ('id,name\n1,Cy\n2,Dee\n---\nid,customer_id,amount\n1,1,10\n2,2,5\n3,2,5\n', 'Cy 10\nDee 10\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\nmerged = customers.merge(orders, left_on='id', right_on='customer_id', how='inner')\ntotals = merged.groupby('name')['amount'].sum().sort_index()\nfor name, total in totals.items():\n    print(name, total)\n"},
    {'technology': 'pandas', 'topic': 'merging', 'name': 'Merge on Differently Named Columns', 'slug': 'merge-on-differently-named-columns', 'description': "Standard input contains two CSV blocks separated by a line containing exactly ---: a customers table (id, name), then an orders table (id, customer_id, amount). Merge them explicitly with left_on='id' and right_on='customer_id', then print how many matched rows resulted.", 'input_format': 'Two CSV blocks separated by a line of exactly ---: customers (id,name), then orders (id,customer_id,amount).', 'output_format': 'Print the number of matched rows.', 'constraints': 'None.', 'examples': [{'input': 'id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50\n2,2,20', 'output': '2'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 4, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\n# merged = customers.merge(orders, left_on='id', right_on='customer_id', how='inner'); print len(merged)\n", 'tests': [('id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50\n2,2,20\n', '2\n', False, 1), ('id,name\n1,Cy\n2,Dee\n---\nid,customer_id,amount\n1,1,10\n2,1,15\n3,2,5\n', '3\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\nmerged = customers.merge(orders, left_on='id', right_on='customer_id', how='inner')\nprint(len(merged))\n"},
    {'technology': 'pandas', 'topic': 'merging', 'name': 'Find Unmatched Rows', 'slug': 'find-unmatched-rows', 'description': "Standard input contains two CSV blocks separated by a line containing exactly ---: a customers table (id, name), then an orders table (id, customer_id, amount). Using a left merge with indicator=True, print the name of every customer with no matching order (indicator value 'left_only'), ordered alphabetically.", 'input_format': 'Two CSV blocks separated by a line of exactly ---: customers (id,name), then orders (id,customer_id,amount).', 'output_format': 'Print the name of each customer with no orders.', 'constraints': 'None.', 'examples': [{'input': 'id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50', 'output': 'Ben'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 5, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\n# merged = customers.merge(orders, left_on='id', right_on='customer_id', how='left', indicator=True)\n# unmatched = merged[merged['_merge']=='left_only'].sort_values('name'); print each name\n", 'tests': [('id,name\n1,Ana\n2,Ben\n---\nid,customer_id,amount\n1,1,50\n', 'Ben\n', False, 1), ('id,name\n1,Cy\n2,Dee\n3,Eli\n---\nid,customer_id,amount\n1,3,5\n', 'Cy\nDee\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text))\norders = pd.read_csv(io.StringIO(right_text))\nmerged = customers.merge(orders, left_on='id', right_on='customer_id', how='left', indicator=True)\nunmatched = merged[merged['_merge'] == 'left_only'].sort_values('name')\nfor value in unmatched['name']:\n    print(value)\n"},
    {'technology': 'pandas', 'topic': 'joining', 'name': 'Join on the Index', 'slug': 'join-on-the-index', 'description': 'Standard input contains two CSV blocks separated by a line containing exactly ---: a customers table (id, name) and a profiles table (id, city), both indexed by id. Use DataFrame.join to combine them on their shared index, then print name and city for every row, ordered by id.', 'input_format': 'Two CSV blocks separated by a line of exactly ---: customers (id,name), then profiles (id,city).', 'output_format': "Print each row's name and city, ordered by id.", 'constraints': 'None.', 'examples': [{'input': 'id,name\n1,Ana\n2,Ben\n---\nid,city\n1,Chennai\n2,Pune', 'output': '   name     city\nid              \n1   Ana  Chennai\n2   Ben     Pune'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 1, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text)).set_index('id')\nprofiles = pd.read_csv(io.StringIO(right_text)).set_index('id')\n# joined = customers.join(profiles).sort_index(); print name and city for each row\n", 'tests': [('id,name\n1,Ana\n2,Ben\n---\nid,city\n1,Chennai\n2,Pune\n', '   name     city\nid              \n1   Ana  Chennai\n2   Ben     Pune\n', False, 1), ('id,name\n1,Cy\n2,Dee\n---\nid,city\n1,Delhi\n2,Goa\n', '   name   city\nid            \n1    Cy  Delhi\n2   Dee    Goa\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text)).set_index('id')\nprofiles = pd.read_csv(io.StringIO(right_text)).set_index('id')\njoined = customers.join(profiles).sort_index()\nprint(joined[['name', 'city']].to_string())\n"},
    {'technology': 'pandas', 'topic': 'joining', 'name': 'A Left Join With Missing Matches', 'slug': 'a-left-join-with-missing-matches', 'description': "Standard input contains two CSV blocks separated by a line containing exactly ---: a customers table (id, name) and a profiles table (id, city) that may not cover every customer. Join with how='left', then print how many rows have a missing city, using isna.", 'input_format': 'Two CSV blocks separated by a line of exactly ---: customers (id,name), then profiles (id,city).', 'output_format': 'Print the count of customers with no matching profile.', 'constraints': 'None.', 'examples': [{'input': 'id,name\n1,Ana\n2,Ben\n---\nid,city\n1,Chennai', 'output': '1'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 2, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text)).set_index('id')\nprofiles = pd.read_csv(io.StringIO(right_text)).set_index('id')\n# joined = customers.join(profiles, how='left'); print joined['city'].isna().sum()\n", 'tests': [('id,name\n1,Ana\n2,Ben\n---\nid,city\n1,Chennai\n', '1\n', False, 1), ('id,name\n1,Cy\n2,Dee\n3,Eli\n---\nid,city\n2,Goa\n', '2\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text)).set_index('id')\nprofiles = pd.read_csv(io.StringIO(right_text)).set_index('id')\njoined = customers.join(profiles, how='left')\nprint(joined['city'].isna().sum())\n"},
    {'technology': 'pandas', 'topic': 'joining', 'name': 'An Inner Join', 'slug': 'an-inner-join-pandas', 'description': "Standard input contains two CSV blocks separated by a line containing exactly ---: a customers table (id, name) and a profiles table (id, city). Join with how='inner' so only customers with a profile remain, then print how many rows resulted.", 'input_format': 'Two CSV blocks separated by a line of exactly ---: customers (id,name), then profiles (id,city).', 'output_format': 'Print the number of matched rows.', 'constraints': 'None.', 'examples': [{'input': 'id,name\n1,Ana\n2,Ben\n---\nid,city\n1,Chennai', 'output': '1'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 3, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text)).set_index('id')\nprofiles = pd.read_csv(io.StringIO(right_text)).set_index('id')\n# joined = customers.join(profiles, how='inner'); print len(joined)\n", 'tests': [('id,name\n1,Ana\n2,Ben\n---\nid,city\n1,Chennai\n', '1\n', False, 1), ('id,name\n1,Cy\n2,Dee\n3,Eli\n---\nid,city\n1,Delhi\n3,Goa\n', '2\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text)).set_index('id')\nprofiles = pd.read_csv(io.StringIO(right_text)).set_index('id')\njoined = customers.join(profiles, how='inner')\nprint(len(joined))\n"},
    {'technology': 'pandas', 'topic': 'joining', 'name': 'Join With Overlapping Column Names', 'slug': 'join-with-overlapping-column-names', 'description': "Standard input contains two CSV blocks separated by a line containing exactly ---: two tables that both have a column named status (a customers table with id, name, status, then a profiles table with id, city, status), both indexed by id. Join them using suffixes ('_customer', '_profile') to disambiguate the repeated column, then print the resulting column names, comma-separated.", 'input_format': 'Two CSV blocks separated by a line of exactly ---: customers (id,name,status), then profiles (id,city,status).', 'output_format': "Print the joined DataFrame's column names, comma-separated.", 'constraints': 'None.', 'examples': [{'input': 'id,name,status\n1,Ana,active\n2,Ben,active\n---\nid,city,status\n1,Chennai,verified\n2,Pune,pending', 'output': 'name,status_customer,city,status_profile'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 4, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text)).set_index('id')\nprofiles = pd.read_csv(io.StringIO(right_text)).set_index('id')\n# joined = customers.join(profiles, lsuffix='_customer', rsuffix='_profile')\n# print ','.join(joined.columns)\n", 'tests': [('id,name,status\n1,Ana,active\n2,Ben,active\n---\nid,city,status\n1,Chennai,verified\n2,Pune,pending\n', 'name,status_customer,city,status_profile\n', False, 1), ('id,name,status\n1,Cy,x\n---\nid,city,status\n1,Delhi,y\n', 'name,status_customer,city,status_profile\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nleft_text, right_text = text.split('\\n---\\n')\ncustomers = pd.read_csv(io.StringIO(left_text)).set_index('id')\nprofiles = pd.read_csv(io.StringIO(right_text)).set_index('id')\njoined = customers.join(profiles, lsuffix='_customer', rsuffix='_profile')\nprint(','.join(joined.columns))\n"},
    {'technology': 'pandas', 'topic': 'joining', 'name': 'Concatenate Two DataFrames', 'slug': 'concatenate-two-dataframes', 'description': 'Standard input contains two CSV blocks separated by a line containing exactly ---, both with columns id, name, score (two batches of students). Use pd.concat to stack them into one DataFrame, then print how many total rows it has.', 'input_format': 'Two CSV blocks separated by a line of exactly ---, both with columns id,name,score.', 'output_format': 'Print the combined row count.', 'constraints': 'None.', 'examples': [{'input': 'id,name,score\n1,Ana,82\n2,Ben,59\n---\nid,name,score\n3,Cy,91', 'output': '3'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 5, 'starter': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nfirst_text, second_text = text.split('\\n---\\n')\nfirst = pd.read_csv(io.StringIO(first_text))\nsecond = pd.read_csv(io.StringIO(second_text))\n# combined = pd.concat([first, second]); print len(combined)\n", 'tests': [('id,name,score\n1,Ana,82\n2,Ben,59\n---\nid,name,score\n3,Cy,91\n', '3\n', False, 1), ('id,name,score\n1,Dee,5\n---\nid,name,score\n2,Eli,6\n3,Fay,7\n', '3\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\nimport io\ntext = sys.stdin.read()\nfirst_text, second_text = text.split('\\n---\\n')\nfirst = pd.read_csv(io.StringIO(first_text))\nsecond = pd.read_csv(io.StringIO(second_text))\ncombined = pd.concat([first, second])\nprint(len(combined))\n"},
    {'technology': 'pandas', 'topic': 'pivot-tables', 'name': 'A Basic Pivot Table', 'slug': 'a-basic-pivot-table', 'description': 'Read CSV text with columns region, product, amount, and build a pivot table with region as the index, product as columns, and amount summed as the values (fill missing combinations with 0). Print the total of the entire pivot table (the sum of all its values).', 'input_format': 'CSV text with a header row: region,product,amount.', 'output_format': 'Print the grand total.', 'constraints': 'None.', 'examples': [{'input': 'region,product,amount\nNorth,A,10\nNorth,B,20\nSouth,A,5', 'output': '35'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 1, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# pivot = df.pivot_table(index='region', columns='product', values='amount', aggfunc='sum', fill_value=0)\n# print pivot.values.sum()\n", 'tests': [('region,product,amount\nNorth,A,10\nNorth,B,20\nSouth,A,5\n', '35\n', False, 1), ('region,product,amount\nEast,A,1\nEast,A,2\nWest,B,3\n', '6\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\npivot = df.pivot_table(index='region', columns='product', values='amount', aggfunc='sum', fill_value=0)\nprint(pivot.values.sum())\n"},
    {'technology': 'pandas', 'topic': 'pivot-tables', 'name': 'Pivot With a Count Aggregation', 'slug': 'pivot-with-a-count-aggregation', 'description': "Read CSV text with columns region, product, amount, and build a pivot table counting how many rows exist per region (index=region, values=amount, aggfunc='count'). Print the count for region 'North'.", 'input_format': 'CSV text with a header row: region,product,amount (includes a North region).', 'output_format': "Print North's row count.", 'constraints': 'None.', 'examples': [{'input': 'region,product,amount\nNorth,A,10\nNorth,B,20\nSouth,A,5', 'output': '2'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 2, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# pivot = df.pivot_table(index='region', values='amount', aggfunc='count')\n# print int(pivot.loc['North', 'amount'])\n", 'tests': [('region,product,amount\nNorth,A,10\nNorth,B,20\nSouth,A,5\n', '2\n', False, 1), ('region,product,amount\nNorth,A,1\nNorth,B,2\nNorth,C,3\n', '3\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\npivot = df.pivot_table(index='region', values='amount', aggfunc='count')\nprint(int(pivot.loc['North', 'amount']))\n"},
    {'technology': 'pandas', 'topic': 'pivot-tables', 'name': 'Pivot With Multiple Value Columns', 'slug': 'pivot-with-multiple-value-columns', 'description': "Read CSV text with columns region, product, amount. Build a pivot table with region as index and both the sum and mean of amount as aggregations (aggfunc=['sum', 'mean']). Print the resulting column names, flattened and comma-separated (use str() on each tuple).", 'input_format': 'CSV text with a header row: region,product,amount.', 'output_format': "Print the pivot's column tuples, comma-separated.", 'constraints': 'None.', 'examples': [{'input': 'region,product,amount\nNorth,A,10\nSouth,A,5', 'output': "('sum', 'amount'),('mean', 'amount')"}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 3, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# pivot = df.pivot_table(index='region', values='amount', aggfunc=['sum','mean'])\n# print ','.join(str(c) for c in pivot.columns)\n", 'tests': [('region,product,amount\nNorth,A,10\nSouth,A,5\n', "('sum', 'amount'),('mean', 'amount')\n", False, 1), ('region,product,amount\nEast,A,1\nWest,B,3\n', "('sum', 'amount'),('mean', 'amount')\n", True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\npivot = df.pivot_table(index='region', values='amount', aggfunc=['sum', 'mean'])\nprint(','.join(str(c) for c in pivot.columns))\n"},
    {'technology': 'pandas', 'topic': 'pivot-tables', 'name': 'Unstack a Grouped Series', 'slug': 'unstack-a-grouped-series', 'description': 'Read CSV text with columns region, product, amount. Group by region and product, sum amount, then use unstack to reshape the result into a wide table (regions as rows, products as columns), filling missing combinations with 0. Print the total of the resulting table.', 'input_format': 'CSV text with a header row: region,product,amount.', 'output_format': 'Print the grand total.', 'constraints': 'None.', 'examples': [{'input': 'region,product,amount\nNorth,A,10\nNorth,B,20\nSouth,A,5', 'output': '35'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 4, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# grouped = df.groupby(['region','product'])['amount'].sum(); wide = grouped.unstack(fill_value=0)\n# print wide.values.sum()\n", 'tests': [('region,product,amount\nNorth,A,10\nNorth,B,20\nSouth,A,5\n', '35\n', False, 1), ('region,product,amount\nEast,A,1\nEast,A,2\nWest,B,3\n', '6\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ngrouped = df.groupby(['region', 'product'])['amount'].sum()\nwide = grouped.unstack(fill_value=0)\nprint(wide.values.sum())\n"},
    {'technology': 'pandas', 'topic': 'pivot-tables', 'name': 'Melt a Wide Table', 'slug': 'melt-a-wide-table', 'description': 'Read CSV text with columns region, A, B (a wide table where A and B are product sales amounts). Use pd.melt to reshape it into long format with columns region, product, amount, then print how many rows the melted table has.', 'input_format': 'CSV text with a header row: region,A,B.', 'output_format': 'Print the melted row count.', 'constraints': 'None.', 'examples': [{'input': 'region,A,B\nNorth,10,20\nSouth,5,15', 'output': '4'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 5, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# melted = df.melt(id_vars=['region'], var_name='product', value_name='amount'); print len(melted)\n", 'tests': [('region,A,B\nNorth,10,20\nSouth,5,15\n', '4\n', False, 1), ('region,A,B\nEast,1,2\n', '2\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\nmelted = df.melt(id_vars=['region'], var_name='product', value_name='amount')\nprint(len(melted))\n"},
    {'technology': 'pandas', 'topic': 'date-and-time-operations', 'name': 'Parse a Date Column', 'slug': 'parse-a-date-column', 'description': 'Read CSV text with columns id, order_date (dates as text like 2026-01-15). Convert order_date to datetime using pd.to_datetime, then print its dtype.', 'input_format': 'CSV text with a header row: id,order_date (ISO dates).', 'output_format': 'Print the converted dtype.', 'constraints': 'None.', 'examples': [{'input': 'id,order_date\n1,2026-01-15\n2,2026-02-20', 'output': 'datetime64[ns]'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 1, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# df['order_date'] = pd.to_datetime(df['order_date']); print the dtype\n", 'tests': [('id,order_date\n1,2026-01-15\n2,2026-02-20\n', 'datetime64[ns]\n', False, 1), ('id,order_date\n1,2025-12-01\n', 'datetime64[ns]\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ndf['order_date'] = pd.to_datetime(df['order_date'])\nprint(df['order_date'].dtype)\n"},
    {'technology': 'pandas', 'topic': 'date-and-time-operations', 'name': 'Extract the Year and Month', 'slug': 'extract-the-year-and-month', 'description': "Read CSV text with columns id, order_date. Convert order_date to datetime, then print each row's year and month, space-separated, one row per line.", 'input_format': 'CSV text with a header row: id,order_date (ISO dates).', 'output_format': "Print each row's year and month.", 'constraints': 'None.', 'examples': [{'input': 'id,order_date\n1,2026-01-15\n2,2026-02-20', 'output': '2026 1\n2026 2'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 2, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# df['order_date'] = pd.to_datetime(df['order_date']); print value.year, value.month for each row\n", 'tests': [('id,order_date\n1,2026-01-15\n2,2026-02-20\n', '2026 1\n2026 2\n', False, 1), ('id,order_date\n1,2025-12-01\n', '2025 12\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ndf['order_date'] = pd.to_datetime(df['order_date'])\nfor value in df['order_date']:\n    print(value.year, value.month)\n"},
    {'technology': 'pandas', 'topic': 'date-and-time-operations', 'name': 'Filter by a Date Range', 'slug': 'filter-by-a-date-range', 'description': 'Read CSV text with columns id, order_date. Convert order_date to datetime, then print the id of every row on or after 2026-01-01, one per line.', 'input_format': 'CSV text with a header row: id,order_date (ISO dates).', 'output_format': 'Print each qualifying id.', 'constraints': 'None.', 'examples': [{'input': 'id,order_date\n1,2026-01-15\n2,2025-12-20', 'output': '1'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 3, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# df['order_date'] = pd.to_datetime(df['order_date'])\n# mask = df['order_date'] >= pd.Timestamp('2026-01-01'); print each matching id\n", 'tests': [('id,order_date\n1,2026-01-15\n2,2025-12-20\n', '1\n', False, 1), ('id,order_date\n1,2025-06-01\n2,2026-03-01\n', '2\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ndf['order_date'] = pd.to_datetime(df['order_date'])\nmask = df['order_date'] >= pd.Timestamp('2026-01-01')\nfor value in df[mask]['id']:\n    print(value)\n"},
    {'technology': 'pandas', 'topic': 'date-and-time-operations', 'name': 'Compute the Difference Between Dates', 'slug': 'compute-the-difference-between-dates', 'description': "Read CSV text with columns id, order_date. Convert order_date to datetime, then print the number of days between each row's date and 2026-01-01, one per line.", 'input_format': 'CSV text with a header row: id,order_date (ISO dates).', 'output_format': "Print each row's day difference.", 'constraints': 'None.', 'examples': [{'input': 'id,order_date\n1,2026-01-11\n2,2025-12-31', 'output': '10\n-1'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 4, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\n# df['order_date'] = pd.to_datetime(df['order_date'])\n# diffs = (df['order_date'] - pd.Timestamp('2026-01-01')).dt.days; print each value\n", 'tests': [('id,order_date\n1,2026-01-11\n2,2025-12-31\n', '10\n-1\n', False, 1), ('id,order_date\n1,2026-01-01\n', '0\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ndf['order_date'] = pd.to_datetime(df['order_date'])\ndiffs = (df['order_date'] - pd.Timestamp('2026-01-01')).dt.days\nfor value in diffs:\n    print(value)\n"},
    {'technology': 'pandas', 'topic': 'date-and-time-operations', 'name': 'Group by Month', 'slug': 'group-by-month', 'description': 'Read CSV text with columns id, order_date, amount. Convert order_date to datetime, group by month (using .dt.month), sum amount, and print MONTH TOTAL for each month present, ordered by month number.', 'input_format': 'CSV text with a header row: id,order_date,amount (ISO dates).', 'output_format': 'Print each month and its total amount.', 'constraints': 'None.', 'examples': [{'input': 'id,order_date,amount\n1,2026-01-05,10\n2,2026-01-20,20\n3,2026-02-01,5', 'output': '1 30\n2 5'}], 'language': 'pandas', 'language_id': 71, 'difficulty': 'Easy', 'order': 5, 'starter': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ndf['order_date'] = pd.to_datetime(df['order_date'])\n# totals = df.groupby(df['order_date'].dt.month)['amount'].sum().sort_index(); print month, total\n", 'tests': [('id,order_date,amount\n1,2026-01-05,10\n2,2026-01-20,20\n3,2026-02-01,5\n', '1 30\n2 5\n', False, 1), ('id,order_date,amount\n1,2025-12-01,1\n2,2025-12-15,2\n', '12 3\n', True, 2)], 'reference_source': "import pandas as pd\nimport sys\n\ndf = pd.read_csv(sys.stdin)\ndf['order_date'] = pd.to_datetime(df['order_date'])\ntotals = df.groupby(df['order_date'].dt.month)['amount'].sum().sort_index()\nfor month, total in totals.items():\n    print(month, total)\n"},
